const deadline = Date.now() + 10000;
while (true) {
  signal.throwIfAborted();
  const state = await page.evaluate(`
    const [searchXPath, resultXPath, emptyXPath] = __args;
    const all = (xpath, root = document) => {
      const rows = document.evaluate(xpath, root, null, XPathResult.ORDERED_NODE_SNAPSHOT_TYPE, null);
      return Array.from({ length: rows.snapshotLength }, (_, i) => rows.snapshotItem(i));
    };
    const searches = all(searchXPath);
    if (searches.length !== 1) throw new Error('Hộp tìm nhóm không còn sẵn sàng');
    const search = searches[0], dialog = search.closest('[role="dialog"]');
    if (!dialog) throw new Error('Không tìm thấy hộp chọn nhóm');
    return { query: search.value, empty: all(emptyXPath).some(el => dialog.contains(el)),
      results: all(resultXPath).filter(el => dialog.contains(el)).map(el => ({
        href: el.href, name: el.textContent.trim()
      })) };
  `, searchXPath, resultsXPath, emptyXPath);
  signal.throwIfAborted();
  if (state.query !== target.name) throw new Error('Tên tìm kiếm nhóm đã thay đổi');
  const matches = state.results.filter(row => {
    try {
      const key = decodeURIComponent(new URL(row.href).pathname.match(/^\/groups\/([^/]+)/i)?.[1] || '').toLowerCase();
      return target.keys.includes(key);
    } catch { return false; }
  });
  if (matches.length > 1) throw new Error('Có nhiều kết quả cùng định danh nhóm');
  if (matches.length === 1) {
    signal.throwIfAborted();
    await page.evaluate(`
      const rows = document.evaluate(__args[0], document, null, XPathResult.ORDERED_NODE_SNAPSHOT_TYPE, null);
      const matches = Array.from({length: rows.snapshotLength}, (_, i) => rows.snapshotItem(i)).filter(el => el.href === __args[1]);
